type Status = Record<string, unknown>;

function element(id: string): HTMLElement {
  const value = document.getElementById(id);
  if (!value) throw new Error("missing control: " + id);
  return value;
}

function input(id: string): HTMLInputElement {
  const value = element(id);
  if (!(value instanceof HTMLInputElement)) throw new Error("not an input: " + id);
  return value;
}

function text(id: string, value: string): void {
  element(id).textContent = value;
}

async function api(endpoint: string, body?: Status, timeoutMs = 5000): Promise<Status> {
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(endpoint, body === undefined ? {
      signal: controller.signal,
    } : {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    const value: unknown = await response.json().catch(() => ({ error: "Réponse serveur invalide" }));
    if (!response.ok) {
      const error = typeof value === "object" && value !== null && "error" in value
        ? String(value.error)
        : "Requête refusée";
      throw new Error(error);
    }
    if (typeof value !== "object" || value === null || Array.isArray(value)) throw new Error("Réponse invalide");
    return value as Status;
  } finally {
    window.clearTimeout(timeout);
  }
}

type Listing = Record<string, unknown>;

function listingValue(row: Listing, ...keys: string[]): string {
  for (const key of keys) {
    const value = row[key];
    if (value !== undefined && value !== null && String(value).trim()) return String(value);
  }
  return "Non renseigné";
}

function listingIdentity(row: Listing, index: number): string {
  return listingValue(row, "_storeKey", "identifiant", "xeId", "xe_id", "id", "canonicalUrl", "canonical_url", "url") === "Non renseigné"
    ? "row-" + String(index)
    : listingValue(row, "_storeKey", "identifiant", "xeId", "xe_id", "id", "canonicalUrl", "canonical_url", "url");
}

function safeHttpUrl(value: unknown): string | null {
  if (typeof value !== "string") return null;
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:" ? url.href : null;
  } catch {
    return null;
  }
}

function listingSource(row: Listing): string | null {
  for (const key of ["url", "canonicalUrl", "canonical_url"]) {
    const href = safeHttpUrl(row[key]);
    if (href) return href;
  }
  return null;
}

const listingCards = new Map<string, HTMLElement>();

function renderListings(rows: unknown[]): void {
  const container = element("announcements");
  const seen = new Set<string>();
  rows.forEach((value, index) => {
    if (typeof value !== "object" || value === null || Array.isArray(value)) return;
    const row = value as Listing;
    const key = listingIdentity(row, index);
    seen.add(key);
    let card = listingCards.get(key);
    if (!card) {
      card = document.createElement("article");
      card.className = "listing";
      card.dataset.listingKey = key;
      const title = document.createElement("h3");
      const facts = document.createElement("p");
      facts.className = "facts";
      const description = document.createElement("p");
      description.className = "description";
      const source = document.createElement("p");
      card.append(title, facts, description, source);
      listingCards.set(key, card);
      container.append(card);
    }
    const title = card.querySelector("h3");
    if (title) {
      title.textContent = listingValue(row, "type_de_bien", "title") + " · Identifiant : "
        + listingValue(row, "identifiant", "xeId", "xe_id", "id", "_storeKey");
    }
    const facts = card.querySelector(".facts");
    if (facts) {
      facts.textContent = "Prix : " + listingValue(row, "prix", "price") + " " + listingValue(row, "devise", "currency")
        + " · Surface : " + listingValue(row, "surface", "area", "size_with_square_meter")
        + " · Localisation : " + listingValue(row, "localisation", "location");
    }
    const description = card.querySelector(".description");
    if (description) description.textContent = "Description : " + listingValue(row, "description");
    const source = card.querySelector("p:last-child");
    if (source) {
      const sourceFocused = document.activeElement === source.querySelector("a");
      source.replaceChildren();
      const href = listingSource(row);
      if (href) {
        const link = document.createElement("a");
        link.href = href;
        link.textContent = "Voir la source";
        link.target = "_blank";
        link.rel = "noopener noreferrer";
        source.append("Source : ", link);
        if (sourceFocused) link.focus();
      } else {
        source.textContent = "Source : Non renseignée";
      }
    }
  });
  for (const [key, card] of listingCards) {
    if (!seen.has(key)) {
      card.remove();
      listingCards.delete(key);
    }
  }
  element("announcementEmpty").hidden = rows.length > 0;
}

function show(state: Status): void {
  text("state", String(state.label ?? state.status ?? "En attente"));
  text("explanation", String(state.reason ?? "Prêt."));
  const captcha = state.pauseType === "captcha" || (state.status === "paused" && /human verification|captcha|challenge/i.test(String(state.reason ?? "")));
  element("captchaNotice").hidden = !captcha;
  const browserLink = element("browserLink");
  browserLink.hidden = !captcha;
  if (captcha && typeof state.browserUrl === "string") browserLink.setAttribute("href", state.browserUrl);
  const resume = element("resume");
  const paused = state.status === "paused" || (typeof state.pauseType === "string" && state.pauseType.length > 0);
  if (resume instanceof HTMLButtonElement) resume.disabled = !paused;
  const rows = Array.isArray(state.rows) ? state.rows : [];
  renderListings(rows);
  text("listingCount", String(rows.length));
  text("counts", "Annonces : " + rows.length);
}

function bind(): void {
  let resumeInFlight = false;
  let viewVersion = 0;
  let protectedErrorVersion = -1;
  let protectedActionError: string | undefined;
  let refreshInFlight = false;
  let refreshRequested = false;

  const refresh = async (): Promise<void> => {
    if (refreshInFlight) {
      refreshRequested = true;
      return;
    }
    refreshInFlight = true;
    const requestVersion = viewVersion;
    try {
      const state = await api("/api/status");
      if (requestVersion === viewVersion && !resumeInFlight) {
        show(state);
        if (protectedErrorVersion === viewVersion && protectedActionError !== undefined) {
          text("explanation", protectedActionError);
        }
      }
    } catch (error) {
      if (requestVersion === viewVersion && !resumeInFlight && protectedErrorVersion !== viewVersion) {
        text("state", "Erreur serveur");
        text("explanation", error instanceof Error ? error.message : String(error));
      }
    } finally {
      refreshInFlight = false;
      if (refreshRequested) {
        refreshRequested = false;
        void refresh();
      }
    }
  };
  const showAnnouncements = (visible: boolean): void => {
    element("announcementsPanel").hidden = !visible;
    element("collectePanel").hidden = visible;
    element("announcementsBottom").hidden = visible;
    element("navAnnouncements").setAttribute("aria-current", String(visible));
    element("navCollecte").setAttribute("aria-current", String(!visible));
  };
  element("navAnnouncements").addEventListener("click", () => showAnnouncements(true));
  element("navCollecte").addEventListener("click", () => showAnnouncements(false));
  element("tabConfiguration").addEventListener("click", () => {
    element("configurationPanel").hidden = false;
    element("suiviPanel").hidden = true;
  });
  element("tabSuivi").addEventListener("click", () => {
    element("configurationPanel").hidden = true;
    element("suiviPanel").hidden = false;
  });
  element("startForm").addEventListener("submit", (event) => {
    event.preventDefault();
    const actionVersion = ++viewVersion;
    void api("/api/start", {
      target: input("target").value.trim() || undefined,
      maxPages: Number(input("maxPages").value),
    }).then((state) => {
      if (actionVersion === viewVersion) {
        viewVersion += 1;
        protectedErrorVersion = -1;
        protectedActionError = undefined;
        show(state);
      }
    }).catch((error: unknown) => {
      if (actionVersion === viewVersion) {
        protectedErrorVersion = actionVersion;
        protectedActionError = error instanceof Error ? error.message : String(error);
        text("explanation", protectedActionError);
      }
    });
  });
  element("cancel").addEventListener("click", () => {
    const actionVersion = ++viewVersion;
    void api("/api/cancel", {}).then((state) => {
      if (actionVersion === viewVersion) {
        viewVersion += 1;
        protectedErrorVersion = -1;
        protectedActionError = undefined;
        show(state);
      }
    }).catch((error: unknown) => {
      if (actionVersion === viewVersion) {
        protectedErrorVersion = actionVersion;
        protectedActionError = error instanceof Error ? error.message : String(error);
        text("explanation", protectedActionError);
      }
    });
  });
  element("resume").addEventListener("click", () => {
    if (resumeInFlight) return;
    const resume = element("resume");
    if (!(resume instanceof HTMLButtonElement) || resume.disabled) return;
    resumeInFlight = true;
    resume.disabled = true;
    const actionVersion = ++viewVersion;
    const statePromise = api("/api/status").then((state) => {
      const captcha = state.pauseType === "captcha" || (state.status === "paused" && /human verification|captcha|challenge/i.test(String(state.reason ?? "")));
      return (captcha ? api("/api/verify-access", {}) : Promise.resolve(state)).then(() => api("/api/resume", {}));
    });
    void statePromise.then((state) => {
      if (actionVersion === viewVersion) {
        viewVersion += 1;
        protectedErrorVersion = -1;
        protectedActionError = undefined;
        show(state);
      }
    }).catch((error: unknown) => {
      if (actionVersion === viewVersion) {
        protectedErrorVersion = actionVersion;
        protectedActionError = error instanceof Error ? error.message : String(error);
        text("explanation", protectedActionError);
      }
      resume.disabled = false;
    }).finally(() => {
      resumeInFlight = false;
    });
  });
  element("scheduleForm").addEventListener("submit", (event) => {
    event.preventDefault();
    void api("/api/schedule", {
      enabled: input("scheduleEnabled").checked,
      time: input("scheduleTime").value,
      timezone: input("scheduleTimezone").value,
    }).then((value) => text("scheduleState", value.enabled ? "Planification activée." : "Planification désactivée."))
      .catch((error: unknown) => text("scheduleState", error instanceof Error ? error.message : String(error)));
  });
  void refresh();
  window.setInterval(() => {
    void refresh();
  }, 1000);
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", bind);
} else {
  bind();
}

import { createRequire } from "node:module";
import { expect, test } from "vitest";
import { startControlServer, type ControlHarness } from "./helpers/attica-control-harness.js";

type Page = {
  goto(url: string): Promise<unknown>;
  locator(selector: string): {
    click(): Promise<void>;
    dispatchEvent(type: string): Promise<void>;
    focus(): Promise<void>;
    textContent(): Promise<string | null>;
  };
  keyboard: {
    press(key: string): Promise<void>;
  };
  on(event: "request", listener: (request: { url(): string }) => void): void;
  route(url: string, handler: (route: {
    request(): { method(): string; url(): string };
    fulfill(options: { status: number; contentType: string; body: string }): Promise<void>;
  }) => Promise<void>): Promise<void>;
  waitForFunction(
    fn: () => boolean,
    arg: undefined,
    options: { timeout: number },
  ): Promise<unknown>;
  close(): Promise<void>;
};

type Browser = {
  newPage(): Promise<Page>;
  close(): Promise<void>;
};

type Chromium = {
  launch(options: { headless: boolean; executablePath: string }): Promise<Browser>;
};

function loadPlaywright(): { chromium: Chromium } {
  const localRequire = createRequire(__filename);
  return localRequire("../browser/node_modules/playwright") as { chromium: Chromium };
}

async function waitForPause(harness: ControlHarness): Promise<void> {
  for (let attempt = 0; attempt < 100; attempt += 1) {
    if (harness.getStore().loadPause().pauseType === "captcha") return;
    await harness.sleep(10);
  }
  throw new Error("CAPTCHA pause was not reached");
}

async function waitForResumeEnabled(page: Page): Promise<void> {
  await page.waitForFunction(() => {
    const button = document.querySelector("#resume");
    return button instanceof HTMLButtonElement && !button.disabled;
  }, undefined, { timeout: 5000 });
}

test("built control button verifies CAPTCHA, preserves refusal, and suppresses duplicate activation", async () => {
  let harness: ControlHarness | undefined;
  let browser: Browser | undefined;
  let page: Page | undefined;
  const requests: string[] = [];
  let releaseVerification: (() => void) | undefined;

  try {
    const { chromium } = loadPlaywright();
    harness = await startControlServer({
      prefix: "attica-control-ui-",
      fakeSessionOptions: { detailMode: "captcha", completeListings: false },
    });
    browser = await chromium.launch({
      headless: true,
      executablePath: process.env.CHROMIUM_PATH || "/usr/bin/chromium",
    });
    page = await browser.newPage();
    page.on("request", (request) => {
    if (request.url().includes("/api/")) requests.push(new URL(request.url()).pathname);
  });

    if (!harness || !browser || !page) throw new Error("browser setup did not complete");
    const activePage = page;
    expect((await harness.httpRequest("POST", "/api/start", {
      target: harness.getFixtureOrigin() + "/page/1",
      maxPages: 1,
    })).status).toBe(202);
    await waitForPause(harness);
    await activePage.goto(harness.serverUrl);
    await waitForResumeEnabled(activePage);

    await activePage.locator("#resume").click();
    await expect.poll(() => activePage.locator("#explanation").textContent(), { timeout: 10000 }).toContain("CAPTCHA verification");
    const refusalStatus = await harness.httpRequest("GET", "/api/status");
    const refusalBody: unknown = JSON.parse(refusalStatus.body);
    expect(refusalStatus.status).toBe(200);
    expect(typeof refusalBody === "object" && refusalBody !== null && "pauseType" in refusalBody && refusalBody.pauseType === "captcha").toBe(true);
    expect(harness.getStore().loadPause().pauseType).toBe("captcha");
    expect(requests.slice(-2)).toEqual(["/api/status", "/api/verify-access"]);
    expect(requests).not.toContain("/api/resume");

    harness.getFakeSession()._setDetailMode("normal");
    const verificationPending = new Promise<void>((resolve) => {
      releaseVerification = resolve;
    });
    harness.getFakeSession()._setHoldContentOpen(verificationPending);
    requests.length = 0;
    await waitForResumeEnabled(activePage);
    await activePage.locator("#resume").click();
    await activePage.locator("#resume").dispatchEvent("click");
    await expect.poll(() => requests.filter((route) => route === "/api/verify-access").length, { timeout: 10000 }).toBe(1);
    expect(requests.filter((route) => route === "/api/resume")).toHaveLength(0);
    if (!releaseVerification) throw new Error("verification release was not prepared");
    releaseVerification();
    harness.getFakeSession()._clearHoldContent();
    await expect.poll(() => requests.filter((route) => route === "/api/resume").length, { timeout: 10000 }).toBe(1);
    expect(requests.filter((route) => route === "/api/verify-access")).toHaveLength(1);
    expect(requests.filter((route) => route === "/api/resume")).toHaveLength(1);
    expect(requests.indexOf("/api/verify-access")).toBeLessThan(requests.indexOf("/api/resume"));
  } finally {
    if (releaseVerification) releaseVerification();
    harness?.getFakeSession()._clearHoldContent();
    await page?.close().catch(() => undefined);
    await browser?.close().catch(() => undefined);
    await harness?.cleanup();
  }
}, 30000);

test("browser startup failure still cleans the owned harness", async () => {
  let harness: ControlHarness | undefined;
  try {
    const { chromium } = loadPlaywright();
    harness = await startControlServer({
      prefix: "attica-control-ui-startup-failure-",
      fakeSessionOptions: { detailMode: "captcha", completeListings: false },
    });
    await expect(chromium.launch({
      headless: true,
      executablePath: "/definitely-not-a-browser",
    })).rejects.toThrow();
  } finally {
    await harness?.cleanup();
  }
});

test("built control button resumes an ordinary pause without verification via Enter", async () => {
  let harness: ControlHarness | undefined;
  let browser: Browser | undefined;
  let page: Page | undefined;
  const requests: string[] = [];

  try {
    const { chromium } = loadPlaywright();
    harness = await startControlServer({
      prefix: "attica-control-ui-ordinary-",
      fakeSessionOptions: { result429Count: 1, retryAfterMode: "seconds:1" },
    });
    browser = await chromium.launch({
      headless: true,
      executablePath: process.env.CHROMIUM_PATH || "/usr/bin/chromium",
    });
    page = await browser.newPage();
    page.on("request", (request) => {
    if (request.url().includes("/api/")) requests.push(new URL(request.url()).pathname);
  });

    expect((await harness.httpRequest("POST", "/api/start", {
      target: harness.getFixtureOrigin() + "/page/1",
      maxPages: 1,
    })).status).toBe(202);
    for (let attempt = 0; attempt < 100; attempt += 1) {
      if (harness.getStore().loadPause().pauseType === "rate-limit") break;
      await harness.sleep(10);
    }
    harness.advanceClock(2000);
    await page.goto(harness.serverUrl);
    await waitForResumeEnabled(page);
    await page.locator("#resume").focus();
    await page.keyboard.press("Enter");
    await expect.poll(() => requests.includes("/api/resume"), { timeout: 10000 }).toBe(true);
    expect(requests).toContain("/api/resume");
    expect(requests).not.toContain("/api/verify-access");
  } finally {
    await page?.close().catch(() => undefined);
    await browser?.close().catch(() => undefined);
    await harness?.cleanup();
  }
});


test("offline failed action keeps its error while refreshed status and rows advance", async () => {
  let harness: ControlHarness | undefined;
  let browser: Browser | undefined;
  let page: Page | undefined;
  let releaseInitialStatus: (() => void) | undefined;

  try {
    const { chromium } = loadPlaywright();
    harness = await startControlServer({ prefix: "attica-control-ui-refresh-error-" });
    browser = await chromium.launch({
      headless: true,
      executablePath: process.env.CHROMIUM_PATH || "/usr/bin/chromium",
    });
    page = await browser.newPage();
    const initialStatus = new Promise<void>((resolve) => {
      releaseInitialStatus = resolve;
    });
    let statusRequests = 0;
    await page.route("**/api/*", async (route) => {
      const request = route.request();
      if (request.url().endsWith("/api/status") && request.method() === "GET") {
        statusRequests += 1;
        if (statusRequests === 1) await initialStatus;
        const state = statusRequests === 1
          ? { status: "idle", label: "Ancien état", reason: "ancienne réponse", rows: [{ identifiant: "old" }] }
          : { status: "idle", label: "État actualisé", reason: "données fraîches", rows: [{ identifiant: "new" }, { identifiant: "newer" }] };
        await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(state) });
        return;
      }
      if (request.url().endsWith("/api/cancel") && request.method() === "POST") {
        await route.fulfill({ status: 503, contentType: "application/json", body: JSON.stringify({ error: "Arrêt refusé hors ligne" }) });
        return;
      }
      await route.fulfill({ status: 404, contentType: "application/json", body: JSON.stringify({ error: "fixture endpoint absent" }) });
    });
    await page.goto(harness.serverUrl);
    await page.locator("#cancel").click();
    await expect.poll(() => page?.locator("#explanation").textContent(), { timeout: 5000 }).toContain("Arrêt refusé hors ligne");
    if (!releaseInitialStatus) throw new Error("initial status release was not prepared");
    releaseInitialStatus();
    await expect.poll(() => page?.locator("#state").textContent(), { timeout: 5000 }).toContain("État actualisé");
    await expect.poll(() => page?.locator("#announcements").textContent(), { timeout: 5000 }).toContain("newer");
    expect(await page.locator("#explanation").textContent()).toContain("Arrêt refusé hors ligne");
    expect(await page.locator("#announcements .listing").count()).toBe(2);
  } finally {
    if (releaseInitialStatus) releaseInitialStatus();
    await page?.close().catch(() => undefined);
    await browser?.close().catch(() => undefined);
    await harness?.cleanup();
  }
});

import { createRequire } from "node:module";
import { expect, test } from "vitest";
import { AtticaStore } from "../browser/attica-store";
import { startControlServer, type ControlHarness } from "./helpers/attica-control-harness.js";

type Locator = {
  click(): Promise<void>;
  count(): Promise<number>;
  textContent(): Promise<string | null>;
  evaluate<T>(fn: (element: HTMLElement) => T): Promise<T>;
};

type Page = {
  goto(url: string): Promise<unknown>;
  locator(selector: string): Locator;
  waitForTimeout(ms: number): Promise<void>;
  close(): Promise<void>;
};

type BrowserContext = {
  newPage(): Promise<Page>;
  close(): Promise<void>;
};

type Browser = {
  newContext(options: { serviceWorkers: "block" }): Promise<BrowserContext>;
  close(): Promise<void>;
};

type Chromium = {
  launch(options: { headless: boolean; executablePath: string }): Promise<Browser>;
};

function loadPlaywright(): { chromium: Chromium } {
  const localRequire = createRequire(__filename);
  return localRequire("../browser/node_modules/playwright") as { chromium: Chromium };
}

async function waitForCards(page: Page, count: number): Promise<void> {
  for (let attempt = 0; attempt < 100; attempt += 1) {
    if (await page.locator("#announcements .listing").count() === count) return;
    await page.waitForTimeout(20);
  }
  throw new Error("timed out waiting for " + String(count) + " listing cards");
}

async function openPage(harness: ControlHarness): Promise<{ browser: Browser; context: BrowserContext; page: Page }> {
  const { chromium } = loadPlaywright();
  const browser = await chromium.launch({
    headless: true,
    executablePath: process.env.CHROMIUM_PATH || "/usr/bin/chromium",
  });
  let context: BrowserContext | undefined;
  let page: Page | undefined;
  try {
    context = await browser.newContext({ serviceWorkers: "block" });
    page = await context.newPage();
    await page.goto(harness.serverUrl + "/");
    return { browser, context, page };
  } catch (error) {
    await page?.close().catch(() => undefined);
    await context?.close().catch(() => undefined);
    await browser.close().catch(() => undefined);
    throw error;
  }
}

async function closePage(harness: ControlHarness, browser: Browser, context: BrowserContext, page: Page): Promise<void> {
  await page.close().catch(() => undefined);
  await context.close().catch(() => undefined);
  await browser.close().catch(() => undefined);
  await harness.cleanup();
}

test("built Annonces renders retained rows, empty state, safe text and deduplicated updates", async () => {
  const seededHarness = await startControlServer({ prefix: "announcements-seeded-" });
  let seededBrowser: Browser | undefined;
  let seededContext: BrowserContext | undefined;
  let seededPage: Page | undefined;
  try {
    const seededStore = seededHarness.getStore() as AtticaStore;
    seededStore.saveListing({
      identifiant: "retained-1",
      type_de_bien: "Appartement <em>central</em>",
      prix: 250000,
      devise: "EUR",
      surface: 58,
      localisation: "Athènes \"centre\"",
      description: "<img src=x onerror=alert(1)>",
      url: "https://example.test/listing/retained-1",
    });
    ({ browser: seededBrowser, context: seededContext, page: seededPage } = await openPage(seededHarness));
    await seededPage.locator("#navAnnouncements").click();
    await waitForCards(seededPage, 1);
    expect(await seededPage.locator("#announcementEmpty").evaluate((value) => value.hasAttribute("hidden"))).toBe(true);
    const seededText = await seededPage.locator("#announcements").textContent();
    expect(seededText).toContain("retained-1");
    expect(seededText).toContain("<em>central</em>");
    expect(seededText).toContain("250000");
    expect(seededText).toContain("58");
    expect(seededText).toContain("Athènes \"centre\"");
    expect(seededText).toContain("<img src=x onerror=alert(1)>");
    expect(seededText).toContain("Description : <img src=x onerror=alert(1)>");
    expect(await seededPage.locator("#announcements em").count()).toBe(0);
    expect(await seededPage.locator("#announcements script").count()).toBe(0);
    expect(await seededPage.locator("#announcements a").evaluate((value) => value.getAttribute("href"))).toBe("https://example.test/listing/retained-1");
  } finally {
    if (seededBrowser && seededContext && seededPage) await closePage(seededHarness, seededBrowser, seededContext, seededPage);
    else await seededHarness.cleanup();
  }

  const emptyHarness = await startControlServer({ prefix: "announcements-empty-" });
  let emptyBrowser: Browser | undefined;
  let emptyContext: BrowserContext | undefined;
  let emptyPage: Page | undefined;
  try {
    ({ browser: emptyBrowser, context: emptyContext, page: emptyPage } = await openPage(emptyHarness));
    await emptyPage.locator("#navAnnouncements").click();
    await waitForCards(emptyPage, 0);
    expect(await emptyPage.locator("#announcementEmpty").evaluate((value) => !value.hasAttribute("hidden"))).toBe(true);
    (emptyHarness.getStore() as AtticaStore).saveListing({
      identifiant: "retained-2",
      prix: 180000,
      url: "javascript:alert(1)",
      description: "later",
    });
    await waitForCards(emptyPage, 1);
    expect(await emptyPage.locator("#announcements a").count()).toBe(0);
    expect(await emptyPage.locator("#announcements").textContent()).toContain("Description : later");
    (emptyHarness.getStore() as AtticaStore).saveListing({
      identifiant: "retained-3",
      prix: 190000,
      url: "http://example.test/listing/retained-3",
      description: "second later row",
    });
    await waitForCards(emptyPage, 2);
    expect(await emptyPage.locator("#announcements .listing").count()).toBe(2);
    expect(await emptyPage.locator("#announcements").textContent()).toContain("Description : second later row");
    expect(await emptyPage.locator("#announcements a").evaluate((value) => value.getAttribute("href"))).toBe("http://example.test/listing/retained-3");
    (emptyHarness.getStore() as AtticaStore).saveListing({
      identifiant: "retained-3",
      prix: 190000,
      url: "http://example.test/listing/retained-3",
      description: "same identifier retry",
    });
    await emptyPage.waitForTimeout(1100);
    expect(await emptyPage.locator("#announcements .listing").count()).toBe(2);
    expect(await emptyPage.locator("#announcementEmpty").evaluate((value) => value.hasAttribute("hidden"))).toBe(true);
  } finally {
    if (emptyBrowser && emptyContext && emptyPage) await closePage(emptyHarness, emptyBrowser, emptyContext, emptyPage);
    else await emptyHarness.cleanup();
  }
});

import { defineConfig } from "vite";

export default defineConfig({
  root: "browser",
  build: {
    outDir: "../dist/browser-assets",
    emptyOutDir: true,
    rollupOptions: {
      input: "browser/control.html",
    },
  },
});

"use strict";
function element(id) {
    const value = document.getElementById(id);
    if (!value)
        throw new Error("missing control: " + id);
    return value;
}
function input(id) {
    const value = element(id);
    if (!(value instanceof HTMLInputElement))
        throw new Error("not an input: " + id);
    return value;
}
function text(id, value) {
    element(id).textContent = value;
}
async function api(endpoint, body, timeoutMs = 5000) {
    const controller = new AbortController();
    const timeout = window.setTimeout(() => controller.abort(), timeoutMs);
    try {
        const response = await fetch(endpoint, body === undefined ? {
            signal: controller.signal,
        } : {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify(body),
            signal: controller.signal,
        });
        const value = await response.json().catch(() => ({ error: "Réponse serveur invalide" }));
        if (!response.ok) {
            const error = typeof value === "object" && value !== null && "error" in value
                ? String(value.error)
                : "Requête refusée";
            throw new Error(error);
        }
        if (typeof value !== "object" || value === null || Array.isArray(value))
            throw new Error("Réponse invalide");
        return value;
    }
    finally {
        window.clearTimeout(timeout);
    }
}
function listingValue(row, ...keys) {
    for (const key of keys) {
        const value = row[key];
        if (value !== undefined && value !== null && String(value).trim())
            return String(value);
    }
    return "Non renseigné";
}
function listingIdentity(row, index) {
    return listingValue(row, "_storeKey", "identifiant", "xeId", "xe_id", "id", "canonicalUrl", "canonical_url", "url") === "Non renseigné"
        ? "row-" + String(index)
        : listingValue(row, "_storeKey", "identifiant", "xeId", "xe_id", "id", "canonicalUrl", "canonical_url", "url");
}
function safeHttpUrl(value) {
    if (typeof value !== "string")
        return null;
    try {
        const url = new URL(value);
        return url.protocol === "http:" || url.protocol === "https:" ? url.href : null;
    }
    catch {
        return null;
    }
}
function listingSource(row) {
    for (const key of ["url", "canonicalUrl", "canonical_url"]) {
        const href = safeHttpUrl(row[key]);
        if (href)
            return href;
    }
    return null;
}
const listingCards = new Map();
function renderListings(rows) {
    const container = element("announcements");
    const seen = new Set();
    rows.forEach((value, index) => {
        if (typeof value !== "object" || value === null || Array.isArray(value))
            return;
        const row = value;
        const key = listingIdentity(row, index);
        seen.add(key);
        let card = listingCards.get(key);
        if (!card) {
            card = document.createElement("article");
            card.className = "listing";
            card.dataset.listingKey = key;
            const title = document.createElement("h3");
            const facts = document.createElement("p");
            facts.className = "facts";
            const description = document.createElement("p");
            description.className = "description";
            const source = document.createElement("p");
            card.append(title, facts, description, source);
            listingCards.set(key, card);
            container.append(card);
        }
        const title = card.querySelector("h3");
        if (title) {
            title.textContent = listingValue(row, "type_de_bien", "title") + " · Identifiant : "
                + listingValue(row, "identifiant", "xeId", "xe_id", "id", "_storeKey");
        }
        const facts = card.querySelector(".facts");
        if (facts) {
            facts.textContent = "Prix : " + listingValue(row, "prix", "price") + " " + listingValue(row, "devise", "currency")
                + " · Surface : " + listingValue(row, "surface", "area", "size_with_square_meter")
                + " · Localisation : " + listingValue(row, "localisation", "location");
        }
        const description = card.querySelector(".description");
        if (description)
            description.textContent = "Description : " + listingValue(row, "description");
        const source = card.querySelector("p:last-child");
        if (source) {
            const sourceFocused = document.activeElement === source.querySelector("a");
            source.replaceChildren();
            const href = listingSource(row);
            if (href) {
                const link = document.createElement("a");
                link.href = href;
                link.textContent = "Voir la source";
                link.target = "_blank";
                link.rel = "noopener noreferrer";
                source.append("Source : ", link);
                if (sourceFocused)
                    link.focus();
            }
            else {
                source.textContent = "Source : Non renseignée";
            }
        }
    });
    for (const [key, card] of listingCards) {
        if (!seen.has(key)) {
            card.remove();
            listingCards.delete(key);
        }
    }
    element("announcementEmpty").hidden = rows.length > 0;
}
function show(state) {
    text("state", String(state.label ?? state.status ?? "En attente"));
    text("explanation", String(state.reason ?? "Prêt."));
    const captcha = state.pauseType === "captcha" || (state.status === "paused" && /human verification|captcha|challenge/i.test(String(state.reason ?? "")));
    element("captchaNotice").hidden = !captcha;
    const browserLink = element("browserLink");
    browserLink.hidden = !captcha;
    if (captcha && typeof state.browserUrl === "string")
        browserLink.setAttribute("href", state.browserUrl);
    const resume = element("resume");
    const paused = state.status === "paused" || (typeof state.pauseType === "string" && state.pauseType.length > 0);
    if (resume instanceof HTMLButtonElement)
        resume.disabled = !paused;
    const rows = Array.isArray(state.rows) ? state.rows : [];
    renderListings(rows);
    text("listingCount", String(rows.length));
    text("counts", "Annonces : " + rows.length);
}
function bind() {
    let resumeInFlight = false;
    let viewVersion = 0;
    let protectedErrorVersion = -1;
    let refreshInFlight = false;
    let refreshRequested = false;
    const refresh = async () => {
        if (refreshInFlight) {
            refreshRequested = true;
            return;
        }
        refreshInFlight = true;
        const requestVersion = viewVersion;
        try {
            const state = await api("/api/status");
            if (requestVersion === viewVersion && !resumeInFlight && protectedErrorVersion !== viewVersion)
                show(state);
        }
        catch (error) {
            if (requestVersion === viewVersion && !resumeInFlight && protectedErrorVersion !== viewVersion) {
                text("state", "Erreur serveur");
                text("explanation", error instanceof Error ? error.message : String(error));
            }
        }
        finally {
            refreshInFlight = false;
            if (refreshRequested) {
                refreshRequested = false;
                void refresh();
            }
        }
    };
    const showAnnouncements = (visible) => {
        element("announcementsPanel").hidden = !visible;
        element("collectePanel").hidden = visible;
        element("announcementsBottom").hidden = visible;
        element("navAnnouncements").setAttribute("aria-current", String(visible));
        element("navCollecte").setAttribute("aria-current", String(!visible));
    };
    element("navAnnouncements").addEventListener("click", () => showAnnouncements(true));
    element("navCollecte").addEventListener("click", () => showAnnouncements(false));
    element("tabConfiguration").addEventListener("click", () => {
        element("configurationPanel").hidden = false;
        element("suiviPanel").hidden = true;
    });
    element("tabSuivi").addEventListener("click", () => {
        element("configurationPanel").hidden = true;
        element("suiviPanel").hidden = false;
    });
    element("startForm").addEventListener("submit", (event) => {
        event.preventDefault();
        const actionVersion = ++viewVersion;
        void api("/api/start", {
            target: input("target").value.trim() || undefined,
            maxPages: Number(input("maxPages").value),
        }).then((state) => {
            if (actionVersion === viewVersion) {
                viewVersion += 1;
                show(state);
            }
        }).catch((error) => {
            if (actionVersion === viewVersion) {
                protectedErrorVersion = actionVersion;
                text("explanation", error instanceof Error ? error.message : String(error));
            }
        });
    });
    element("cancel").addEventListener("click", () => {
        const actionVersion = ++viewVersion;
        void api("/api/cancel", {}).then((state) => {
            if (actionVersion === viewVersion) {
                viewVersion += 1;
                show(state);
            }
        }).catch((error) => {
            if (actionVersion === viewVersion) {
                protectedErrorVersion = actionVersion;
                text("explanation", error instanceof Error ? error.message : String(error));
            }
        });
    });
    element("resume").addEventListener("click", () => {
        if (resumeInFlight)
            return;
        const resume = element("resume");
        if (!(resume instanceof HTMLButtonElement) || resume.disabled)
            return;
